def solve(xs: list[int]) -> int:
    """Return the length of the longest run of consecutive elements
    that all share the same parity (all even or all odd).
    A single element counts as a run of length 1.
    """
    if not xs:
        return 0
    best = 1
    cur = 1
    prev_parity = xs[0] & 1
    for x in xs[1:]:
        parity = x & 1
        if parity == prev_parity:
            cur += 1
            if cur > best:
                best = cur
        else:
            cur = 1
            prev_parity = parity
    return best

def solve(xs: list[int]) -> int:
    n = len(xs)
    if n <= 1:
        return n
    up = 1
    down = 1
    for i in range(1, n):
        if xs[i] > xs[i-1]:
            up = down + 1
        elif xs[i] < xs[i-1]:
            down = up + 1
    return max(up, down)
